interface.definition:
a!localVariables(
  local!selectedTab: 1,
  local!userGroup: reject(
    fn!isnull,
    #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11617061"(
      a!flatten(
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(loggedInUser()),
          expression: {
            a!localVariables(
              local!userGroup: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3374322"(fv!item),
              local!groups: #"84db40b3-cca2-4b5f-8ab5-3e646ecb446a"(parentGroups: local!userGroup),
              if(
                a!isNullOrEmpty(local!groups),
                local!userGroup,
                { local!groups, local!userGroup }
              )
            )
          }
        )
      )
    )
  ),
  local!isUserDppOps: isusermemberofgroups(
    loggedInUser(),
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922"
  ),
  local!assignee: if(
    local!selectedTab = 1,
    {
      loggedInUser(),
      touniformstring(local!userGroup)
    },
    null
  ),
  local!myTaskModuleFilter,
  local!myTasksFirstNameFilter,
  local!myTasksSubPostionFilter,
  local!myTasksFiscalYearFilter,
  local!myTasksStatusFilter,
  local!allTasksStatusFilter,

  local!allTaskModuleFilter,
  local!user: a!refreshVariable(
    value: user(loggedInUser(), "username"),
    refreshOnReferencedVarChange: true
  ),
  local!userBU: a!refreshVariable(
    value: union(
      reject(
        fn!isnull,
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(user: loggedInUser()),
          expression: {
            a!localVariables(
              local!groupName: group(fv!item, "groupName"),
              local!list: split(local!groupName, " "),
              local!length: length(local!list),
              if(
                and(
                  local!length > 2,
                  contains(local!list, "CAW"),
                  or(
                    contains(local!list, "BUPPP"),
                    contains(local!list, "BUPIC"),
                    contains(local!list, "BUPPP_BUPIC"),
                    contains(local!list, "BUCos"),
                    contains(local!list, "CoS/Delegate")
                  )
                ),
                joinarray(
                  remove(local!list, { 1, local!length }),
                  " "
                ),
                null
              )
            )
          }
        )
      ),
      reject(
        fn!isnull,
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(user: loggedInUser()),
          expression: {
            a!localVariables(
              local!groupName: group(fv!item, "groupName"),
              local!list: split(local!groupName, " "),
              local!length: length(local!list),
              if(
                and(
                  local!length > 2,
                  contains(local!list, "CAW"),
                  or(
                    contains(local!list, "BUPPP"),
                    contains(local!list, "BUPIC"),
                    contains(local!list, "BUPPP_BUPIC"),
                    contains(local!list, "BUCos"),
                    contains(local!list, "CoS/Delegate")
                  )
                ),
                joinarray(
                  remove(local!list, { 1, local!length }),
                  " "
                ),
                null
              )
            )
          }
        )
      )
    ),
    refreshAlways: true
  ),
  local!selectedTaskIds,
  local!unfilteredTasks: a!refreshVariable(
    value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177276"(
      returnCDT: true,
      isCompleted: false,
      isAssigneeGroup: false
    ),
    refreshAlways: true()
  ),
  local!allTasks: a!refreshVariable(
    value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177276"(
      returnCDT: true,
      isCompleted: false,
      assignee: if(
        #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!assignee),
        null,
        local!assignee
      ),
      originatingBU: local!userBU,
      returnBU: local!userBU,

      taskStatus: if(
        local!selectedTab = 1,
        if(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!myTasksStatusFilter),
          null,
          local!myTasksStatusFilter
        ),
        if(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!allTasksStatusFilter),
          null,
          local!allTasksStatusFilter
        )
      ),
      moduleName: if(
        local!selectedTab = 1,
        if(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!myTaskModuleFilter),
          null,
          local!myTaskModuleFilter
        ),
        if(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!allTaskModuleFilter),
          null,
          local!allTaskModuleFilter
        )
      ),
      firstName: if(
        local!selectedTab = 1,
        if(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!myTasksFirstNameFilter),
          null,
          if(
            local!myTaskModuleFilter = "ASK",
            null,
            local!myTasksFirstNameFilter
          )

        ),
        null
      ),
      subPosition: if(
        local!selectedTab = 1,
        if(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!myTasksSubPostionFilter),
          null,
          if(
            local!myTaskModuleFilter = "ASK",
            null,
            local!myTasksSubPostionFilter
          )
        ),
        null
      ),
      fiscalYear: if(
        local!selectedTab = 1,
        if(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!myTasksFiscalYearFilter),
          null,
          local!myTasksFiscalYearFilter
        ),
        null
      )
    ),
    refreshAlways: true()
  ),
  local!taskStatuses: a!refreshVariable(
    value: index(local!allTasks, "taskStatus", null),
    refreshOnReferencedVarChange: false
  ),
  local!taskStatusesDistinct: a!refreshVariable(
    value: union(local!taskStatuses, local!taskStatuses),
    refreshOnReferencedVarChange: false
  ),
  local!assigneeRefData: index(local!unfilteredTasks, "assignee", {}),
  local!assigneeRefDataUnique: reject(
    fn!isnull,
    union(
      local!assigneeRefData,
      local!assigneeRefData
    )
  ),
  local!showFilters: false,
  local!collapseNav: true,
  local!activeCollapsibleNavSection: 1,
  local!collapsibleNavSections: {
    a!map(
      name: "My Tasks",
      icon: "tasks-alt",
      showWhen: true
    ),
    a!map(
      name: "All Tasks",
      icon: "tasks",
      showWhen: local!isUserDppOps
    ),
    a!map(
      name: "Recent Activities",
      icon: "refresh-alt",
      showWhen: true
    ),
    a!map(
      name: "Quick Links",
      icon: "question",
      showWhen: true
    ),

  },
  local!audit: #"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3442778"(
    createdBy: tostring(loggedInUser()),
    createdOn: todatetime(today() - 30),
    returnCDT: true,
    columns: {
      "taskId",
      "requestId",
      "moduleTypeId",
      "version"
    }
  ),
  local!filteredAudit: union(local!audit, local!audit),
  local!recentActivities: a!refreshVariable(
    value: if(
      local!activeCollapsibleNavSection = if(local!isUserDppOps, 3, 2),
      if(
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!audit),
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177276"(
          returnCDT: true,
          taskId: property(local!filteredAudit, "taskId", null)
        ),
        null
      ),
      null
    ),
    refreshAlways: true()
  ),

  {
    #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4622449"(taskStatuses: local!taskStatuses),
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_forEach"(
              items: local!collapsibleNavSections,
              expression: if(
                local!collapseNav,
                {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(
                        icon: fv!item.icon,
                        caption: fv!item.name,
                        link: #"SYSTEM_SYSRULES_dynamicLink"(
                          value: fv!index,
                          saveInto: {
                            local!selectedTab,
                            if(
                              local!selectedTab = 1,
                              a!save(local!user, loggedInUser()),
                              if(
                                local!selectedTab = 2,
                                a!save(local!user, null),
                                {}
                              )
                            )
                          }
                        ),
                        linkStyle: "STANDALONE",
                        color: if(
                          fv!index = local!selectedTab,
                          "ACCENT",
                          "SECONDARY"
                        ),
                        size: "LARGE"
                      )
                    },
                    showWhen: fv!item.showWhen,
                    align: "CENTER",
                    accessibilityText: if(
                      fv!index = local!selectedTab,
                      fv!item.name & " " & "selected",
                      ""
                    )
                  )
                },
                #"SYSTEM_SYSRULES_cardLayout"(
                  contents: #"SYSTEM_SYSRULES_sideBySideLayout"(
                    items: {
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: #"SYSTEM_SYSRULES_richTextIcon"(
                            icon: fv!item.icon,
                            color: if(
                              fv!index = local!selectedTab,
                              "STANDARD",
                              "SECONDARY"
                            ),
                            size: "MEDIUM"
                          ),
                          align: "LEFT"
                        ),
                        width: "MINIMIZE"
                      ),
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: fv!item.name,
                            color: "ACCENT",
                            size: "MEDIUM",
                            style: if(
                              fv!index = local!selectedTab,
                              "STRONG",
                              "PLAIN"
                            )
                          )
                        )
                      )
                    },
                    alignVertical: "MIDDLE"
                  ),
                  link: #"SYSTEM_SYSRULES_dynamicLink"(
                    value: fv!index,
                    saveInto: local!selectedTab
                  ),
                  showWhen: fv!item.showWhen,
                  style: if(
                    fv!index = local!selectedTab,
                    "ACCENT",
                    "NONE"
                  ),
                  showBorder: false,
                  accessibilityText: if(
                    fv!index = local!selectedTab,
                    fv!item.name & " " & "selected",
                    ""
                  )
                )
              )
            ),
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              value: #"SYSTEM_SYSRULES_richTextIcon"(
                icon: if(
                  local!collapseNav,
                  "angle-double-right",
                  "angle-double-left"
                ),
                caption: if(
                  local!collapseNav,
                  "Expand navigation bar",
                  "Collapse navigation bar"
                ),
                link: #"SYSTEM_SYSRULES_dynamicLink"(
                  value: not(local!collapseNav),
                  saveInto: local!collapseNav
                ),
                linkStyle: "STANDALONE",
                color: "SECONDARY",
                size: "MEDIUM"
              ),
              align: "CENTER"
            ),
            #"SYSTEM_SYSRULES_cardLayout"(
              height: "TALL",
              showWhen: not(#"SYSTEM_SYSRULES_isPageWidth"("PHONE")),
              showBorder: false
            )
          },
          width: if(
            local!collapseNav,
            "EXTRA_NARROW",
            "NARROW"
          )
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            choose(
              local!selectedTab,
              /*MY TASKS*/
              #"SYSTEM_SYSRULES_sectionLayout_v1"(
                label: local!collapsibleNavSections.name[1],
                labelSize: "LARGE",
                contents: {
                  #"SYSTEM_SYSRULES_columnsLayout"(
                    columns: {
                      #"SYSTEM_SYSRULES_columnLayout"(),
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                            buttons: {
                              #"SYSTEM_SYSRULES_ButtonWidget"(
                                label: if(
                                  local!showFilters,
                                  "Hide Filters",
                                  "Show Filters"
                                ),
                                icon: "Filter",
                                saveInto: a!save(
                                  local!showFilters,
                                  not(local!showFilters)
                                ),
                                style: "NORMAL"
                              )
                            },
                            align: "END"
                          )
                        },
                        width: "NARROW"
                      )
                    }
                  ),
                  #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3238130"(
                    assigneeRefDataUnique: local!assigneeRefDataUnique,
                    assignees: local!assignee,
                    status: local!myTasksStatusFilter,
                    module: local!myTaskModuleFilter,
                    selectedTab: local!selectedTab,
                    user: local!user,
                    isShowFilters: local!showFilters,
                    taskStatuses: local!taskStatusesDistinct,
                    nameFilter: local!myTasksFirstNameFilter,
                    fiscalYear: local!myTasksFiscalYearFilter,
                    subPosition: local!myTasksSubPostionFilter
                  ),
                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177172"(
                    tasks: local!allTasks,
                    loggedInUser: loggedInUser()
                  )
                },
                divider: "ABOVE",
                dividerWeight: "THIN",
                dividerColor: "ACCENT"
              ),
              /*ALL TASKS*/
              #"SYSTEM_SYSRULES_sectionLayout_v1"(
                label: local!collapsibleNavSections.name[2],
                labelSize: "LARGE",
                contents: {
                  #"SYSTEM_SYSRULES_columnsLayout"(
                    columns: {
                      #"SYSTEM_SYSRULES_columnLayout"(),
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                            buttons: {
                              #"SYSTEM_SYSRULES_ButtonWidget"(
                                label: if(
                                  local!showFilters,
                                  "Hide Filters",
                                  "Show Filters"
                                ),
                                icon: "Filter",
                                saveInto: a!save(
                                  local!showFilters,
                                  not(local!showFilters)
                                ),
                                style: "NORMAL"
                              )
                            },
                            align: "END"
                          )
                        },
                        width: "NARROW"
                      ),
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_cardLayout"(
                            contents: {
                              #"SYSTEM_SYSRULES_richTextDisplayField"(
                                labelPosition: "COLLAPSED",
                                value: {
                                  #"SYSTEM_SYSRULES_richTextIcon"(icon: "mail-forward"),
                                  #"SYSTEM_SYSRULES_richTextItem_v1"(
                                    text: " " & #"_a-0000e6d2-8270-8000-9c03-011c48011c48_4037591",
                                    size: "STANDARD",
                                    style: "STRONG"
                                  )
                                },
                                align: "CENTER"
                              )
                            },
                            link: if(
                              or(
                                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!selectedTaskIds),
                                tointeger(length(local!selectedTaskIds)) > 1
                              ),
                              null,
                              #"SYSTEM_SYSRULES_startProcessLink"(
                                processModel: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_4043086",
                                processParameters: {
                                  taskId: local!selectedTaskIds,
                                  assignee: index(
                                    local!allTasks,
                                    wherecontains(
                                      local!selectedTaskIds,
                                      local!allTasks.taskId
                                    )
                                  ).assignee,
                                  regionId: index(
                                    local!allTasks,
                                    wherecontains(
                                      local!selectedTaskIds,
                                      local!allTasks.taskId
                                    )
                                  ).regionId
                                }
                              )
                            ),
                            style: if(
                              or(
                                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!selectedTaskIds),
                                tointeger(length(local!selectedTaskIds)) > 1
                              ),
                              "STANDARD",
                              "ACCENT"
                            )
                          )
                        },
                        width: "NARROW"
                      )
                    }
                  ),
                  #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3238130"(
                    assigneeRefDataUnique: local!assigneeRefDataUnique,
                    assignees: local!assignee,
                    status: local!allTasksStatusFilter,
                    module: local!allTaskModuleFilter,
                    selectedTab: local!selectedTab,
                    user: local!user,
                    isShowFilters: local!showFilters,
                    taskStatuses: local!taskStatusesDistinct
                  ),
                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177172"(
                    tasks: local!allTasks,
                    selectedTaskIds: local!selectedTaskIds,
                    loggedInUser: loggedInUser(),
                    selectedTab: local!selectedTab
                  )
                },
                showWhen: local!collapsibleNavSections.showWhen[2],
                divider: "ABOVE",
                dividerWeight: "THIN",
                dividerColor: "ACCENT"
              ),
              /*RECENT ACITVITY */
              #"SYSTEM_SYSRULES_sectionLayout_v1"(
                label: local!collapsibleNavSections.name[3],
                labelSize: "LARGE",
                contents: #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4650587"(tasks: local!recentActivities),
                divider: "ABOVE",
                dividerWeight: "THIN",
                dividerColor: "ACCENT"
              ),
              /*QUICK LINKS*/
              #"SYSTEM_SYSRULES_sectionLayout_v1"(
                label: local!collapsibleNavSections.name[local!selectedTab],
                labelSize: "LARGE",
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    value: #"SYSTEM_SYSRULES_richTextHeader"(text: "Documentation", size: "MEDIUM")
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: "Role Definitions",
                        link: #"SYSTEM_SYSRULES_reportLink"(
                          label: "Role Definitions",
                          report: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3196185"
                        ),
                        size: "MEDIUM_PLUS"
                      )
                    },
                    align: "LEFT"
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: "QRG",
                        link: #"SYSTEM_SYSRULES_safeLink"(label: "QRG", uri: #"_a-0000e825-ace1-8000-9c24-011c48011c48_6853147"),
                        size: "MEDIUM_PLUS"
                      )
                    },
                    align: "LEFT"
                  ),

                },
                divider: "ABOVE",
                dividerWeight: "THIN",
                dividerColor: "ACCENT"
              )
            )
          }
        )
      },
      spacing: "SPARSE",
      showDividers: true
    )
  }
)
